export const getConjugatedPuzzles = (difficulty, person, tense) => {
    return CONJUGATED_SENTENCE_PUZZLES.filter(p =>
        p.difficulty === difficulty &&
        (!person || p.person === person) &&
        (!tense || p.tense === tense)
    );
};

export const getRandomConjugatedSentence = (difficulty, person, tense) => {
    const puzzles = getConjugatedPuzzles(difficulty, person, tense);
    return puzzles[Math.floor(Math.random() * puzzles.length)];
};
